import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.z3u3TMv0.js";const k=JSON.parse('{"title":"安装 LocalAI","description":"使用 LocalAI 提供 OpenAI 兼容 API，从 Docker 或二进制安装后连接 MiniTavern。","frontmatter":{"title":"安装 LocalAI","description":"使用 LocalAI 提供 OpenAI 兼容 API，从 Docker 或二进制安装后连接 MiniTavern。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"安装 LocalAI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"使用 LocalAI 提供 OpenAI 兼容 API，从 Docker 或二进制安装后连接 MiniTavern。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/localai/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/localai/install"}]]},"headers":[],"relativePath":"localai/install.md","filePath":"localai/install.md","lastUpdated":1786329914000}'),r={name:"localai/install.md"};function n(o,a,s,d,c,h){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="安装与连接-localai" tabindex="-1">安装与连接（LocalAI） <a class="header-anchor" href="#安装与连接-localai" aria-label="Permalink to &quot;安装与连接（LocalAI）&quot;">​</a></h1><p><a href="https://localai.io/" target="_blank" rel="noreferrer">LocalAI</a> 是本地的 OpenAI 兼容 API 网关，可对接多种后端。适合已经熟悉 Docker、或希望「一个兼容层接多种模型」的用户。</p><h2 id="快速启动-docker-示例" tabindex="-1">快速启动（Docker 示例） <a class="header-anchor" href="#快速启动-docker-示例" aria-label="Permalink to &quot;快速启动（Docker 示例）&quot;">​</a></h2><p>具体镜像名与端口以 <a href="https://localai.io/" target="_blank" rel="noreferrer">官方文档</a> 为准，示意：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local-ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localai/localai:latest</span></span></code></pre></div><p>首次需按文档放入或拉取模型；确认本机可访问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8080/v1/models</span></span></code></pre></div><h2 id="局域网" tabindex="-1">局域网 <a class="header-anchor" href="#局域网" aria-label="Permalink to &quot;局域网&quot;">​</a></h2><ul><li>容器端口映射到宿主机后，防火墙放行 <strong>8080</strong>（或你映射的端口）。</li><li>手机使用：<code>http://YOUR_PC_IP:8080/v1</code>。</li><li>若容器只绑定了错误网卡，检查 Docker 端口发布与宿主机防火墙。</li></ul><h2 id="给-minitavern" tabindex="-1">给 MiniTavern <a class="header-anchor" href="#给-minitavern" aria-label="Permalink to &quot;给 MiniTavern&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填写</th></tr></thead><tbody><tr><td>模型平台</td><td>自定义（OpenAI 兼容）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8080/v1</code></td></tr><tr><td>API Key</td><td>按 LocalAI 是否启用鉴权填写</td></tr><tr><td>模型名</td><td>与 LocalAI 中配置的 model id 一致</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="/ultra_guides/connect-app/minitavern">在 MiniTavern 中配置</a> · <a href="/ultra_guides/local/tools">工具总览</a> · <a href="/ultra_guides/troubleshoot">排错</a></p>',13)])])}const u=t(r,[["render",n]]);export{k as __pageData,u as default}